/* @lc app=leetcode id=3049 lang=kotlin */ class Solution { fun earliestSecondToMarkIndices(nums: IntArray, changeIndices: IntArray): Int = IntArray(nums.size) { -1 }.also { first -> (0 until changeIndices.size).forEach { i -> (changeIndices[i] - 1).let { idx -> if (first[idx] == -1) first[idx] = i } } }.let { first -> { mid: Int -> java.util.PriorityQueue<Int>().let { pq -> (mid downTo 0).fold(0) { cnt, i -> (changeIndices[i] - 1).let { idx -> if (i == first[idx] && nums[idx] > 0) pq.add(nums[idx]).let { if (cnt > 0) cnt - 1 else pq.poll().let { cnt + 1 } } else cnt + 1 } }.let { freeSecs -> nums.sumOf { it.toLong() }.let { totalValSum -> pq.sumOf { it.toLong() }.let { saved -> totalValSum + nums.size - saved - pq.size <= freeSecs } } } } } }.let { check -> generateSequence(Triple(0, changeIndices.size - 1, -1)) { triple -> triple.let { (low, high, ans) -> if (low > high) null else ((low + high) / 2).let { m -> if (check(m)) Triple(low, m - 1, m) else Triple(m + 1, high, ans) } } }.last().let { if (it.third == -1) -1 else it.third + 1 } } }